import ChatModel
import FakeChatServer
import Foundation

enum FakeSeeder {
    struct CustomEmojis: Sendable {
        let shipit: CustomEmojiName
        let lgtm: CustomEmojiName
        let parrot: CustomEmojiName
    }

    private struct Context {
        let server: FakeChatServer
        let account: FakeAccount
        let reactors: [User]
        let emoji: CustomEmojis
        let library: FakeLibrary

        /// An uploaded attachment backed by generated bytes the fake server can actually serve.
        func upload(_ name: String, _ type: String, _ id: String) -> Attachment {
            let item = library.item(type: type, id: id)
            let resource = server.addMedia(item.data, contentType: type, filename: name)
            return Attachment(contentName: name, contentType: type, source: .uploaded(resource))
        }
    }

    private struct Plan {
        var time: Timestamp
        var sender: User
        var text: String
        var annotations: [Annotation] = []
        var attachments: [Attachment] = []
        var deleted = false
        var topLevel = false
    }

    static func seed(
        org: FakeScript.Org, orgIndex: Int, account: FakeAccount, server: FakeChatServer, now: Timestamp,
        emoji: CustomEmojis, library: FakeLibrary, _ random: inout SeededRandom
    ) -> [FakeWorld.Target] {
        let base = 2_000_000_000_000 + orgIndex * 1000
        let people = org.people.enumerated().map { index, name in
            User(name: UserName(unchecked: "users/\(base + index + 1)"), displayName: name)
        }
        let bot = User(name: UserName(unchecked: "users/\(base + 900)"), type: .bot, displayName: org.bot)
        let reactors = FakeScript.reactors.enumerated().map { index, name in
            User(name: UserName(unchecked: "users/\(base + 500 + index)"), displayName: name)
        }
        for person in people { server.setEmail(FakeScript.email(person.displayName ?? "", org: org), for: person) }
        for (index, name) in FakeScript.directoryNames(org: orgIndex).enumerated() {
            let user = User(name: UserName(unchecked: "users/\(base + 700 + index)"), displayName: name)
            server.addDirectoryPerson(user, email: FakeScript.email(name, org: org))
        }
        let context = Context(server: server, account: account, reactors: reactors, emoji: emoji, library: library)
        var targets: [FakeWorld.Target] = []

        for (index, spec) in org.spaces.enumerated() {
            let members = Array(people.shuffled(using: &random).prefix(max(3, people.count - index % 2)))
            let space = server.addSpace(
                .space, displayName: spec.title, members: [account], users: members, threaded: spec.threaded)
            var features: [FakeScript.Feature] = []
            if index == 0 { features = [.mention, .longMessage, .link] }
            if index == 1 { features = [.uploaded, .deleted, .link] }
            if index == 2 { features = [.drive, .mention] }
            var endAgo = [4.0, 35, 130, 420, 1200, 1900][min(index, 5)] * Double.random(in: 0.7...1.3, using: &random)
            // Google deletes history-off messages after a day, so such a conversation only ever shows that day.
            if spec.historyOff {
                endAgo = min(endAgo, 60)
                server.setHistory(on: false, in: space)
            }
            let end = now.date.addingTimeInterval(-endAgo * 60)
            let roots = post(
                context, count: spec.messages, features: features, in: space, end: end, others: members,
                threaded: spec.threaded, &random)
            if orgIndex == 0 { showcase(context, spec.title, space, end: end, others: members) }
            if orgIndex == FakeWorld.redirectOrgIndex, index == 0, let sender = members.first {
                server.post(
                    "Mockup for review", in: space, from: .user(sender),
                    attachments: [context.upload("redirect-check.png", "image/png", "show-png")],
                    at: Timestamp(end.addingTimeInterval(5)))
            }
            setReadState(server, account, space, unread: spec.unread)
            if spec.unreadReplies > 0 {
                // The thread with the most replies is read up to its last few, like replies arriving overnight.
                var replies: [ThreadName: [Message]] = [:]
                for message in server.messages(in: space) where message.isThreadReply {
                    if let thread = message.thread { replies[thread, default: []].append(message) }
                }
                if let (thread, list) = replies.max(by: { $0.value.count < $1.value.count }),
                    list.count > spec.unreadReplies
                {
                    let read = list.sorted { $0.createTime < $1.createTime }[list.count - spec.unreadReplies - 1]
                    server.setThreadReadState(account, thread: thread, lastReadTime: read.createTime)
                }
            }
            if spec.muted {
                server.setNotificationSetting(
                    account, space: space, SpaceNotificationSetting(level: .off, isMuted: true))
            }
            targets.append(
                FakeWorld.Target(
                    account: account, server: server, space: space, senders: members, isBot: false,
                    roots: spec.threaded ? roots : []))
        }

        for (index, dm) in org.directs.enumerated() {
            let endAgo = [12.0, 300, 900][min(index, 2)] * Double.random(in: 0.7...1.3, using: &random)
            let space: SpaceName
            let others: [User]
            switch dm.kind {
            case .person(let personIndex):
                others = [people[personIndex % people.count]]
                space = server.addSpace(.directMessage, members: [account], users: others, threaded: false)
            case .bot:
                others = [bot]
                space = server.addSpace(.directMessage, members: [account], bots: [bot], threaded: false)
            case .group(let indexes):
                others = indexes.map { people[$0 % people.count] }
                space = server.addSpace(.groupChat, members: [account], users: others, threaded: false)
            }
            let isBot = dm.kind == .bot
            post(
                context, count: dm.messages, features: [], in: space,
                end: now.date.addingTimeInterval(-endAgo * 60), others: others, threaded: false, botLines: isBot,
                &random)
            setReadState(server, account, space, unread: dm.unread)
            targets.append(
                FakeWorld.Target(
                    account: account, server: server, space: space, senders: others, isBot: isBot, roots: []))
        }
        return targets
    }

    // MARK: Regular history

    @discardableResult
    private static func post(
        _ context: Context, count: Int, features: [FakeScript.Feature], in space: SpaceName, end: Date,
        others: [User], threaded: Bool, botLines: Bool = false, _ random: inout SeededRandom
    ) -> [ThreadName] {
        let server = context.server
        let account = context.account
        let span = min(46 * 3600 - Date().timeIntervalSince(end), max(2 * 3600, Double(count) * 5400))
        var offsets = (0..<max(0, count - 1)).map { _ in Double.random(in: 0...span, using: &random) }
        offsets.sort(by: >)
        offsets.append(0)
        let times = offsets.map { Timestamp(end.addingTimeInterval(-$0)) }

        var plans: [Plan] = times.map { time in
            let mine = Double.random(in: 0...1, using: &random) < 0.2
            let sender = mine ? account.user : (others.randomElement(using: &random) ?? account.user)
            let pool = botLines ? FakeScript.botLines : FakeScript.chatter
            var plan = Plan(time: time, sender: sender, text: pool.randomElement(using: &random) ?? "ok")
            if !botLines {
                let roll = Double.random(in: 0...1, using: &random)
                if roll < 0.08, let line = FakeScript.emojiLines.randomElement(using: &random) {
                    plan.text = line
                } else if roll < 0.20, let file = FakeScript.attachmentPool.randomElement(using: &random) {
                    plan.attachments = [
                        context.upload(file.name, file.type, "pool-\(Int.random(in: 0...9999, using: &random))")
                    ]
                    if Double.random(in: 0...1, using: &random) < 0.3 { plan.text = "" }
                }
            }
            return plan
        }
        let slots = [count / 4, count / 2, (count * 3) / 4].map { min(max($0, 1), max(0, count - 2)) }
        for (feature, slot) in zip(features, slots) where plans.indices.contains(slot) {
            apply(context, feature, to: &plans[slot], slot: slot, others: others, &random)
        }

        var roots: [Message] = []
        for plan in plans {
            var thread: ThreadName?
            if threaded, !plan.topLevel, !roots.isEmpty, Double.random(in: 0...1, using: &random) < 0.55,
                let root = roots.suffix(4).randomElement(using: &random)
            {
                thread = root.thread
            }
            let message = server.post(
                plan.text, in: space, from: sender(plan.sender, account, botLines), thread: thread,
                annotations: plan.annotations, attachments: plan.attachments, at: plan.time)
            if thread == nil { roots.append(message) }
            if plan.deleted {
                server.delete(message.name, at: plan.time.adding(.seconds(45)))
            } else if !botLines, Double.random(in: 0...1, using: &random) < 0.3 {
                randomReactions(context, message, &random)
            }
        }
        return roots.compactMap(\.thread)
    }

    private static func apply(
        _ context: Context, _ feature: FakeScript.Feature, to plan: inout Plan, slot: Int, others: [User],
        _ random: inout SeededRandom
    ) {
        let account = context.account
        plan.topLevel = true
        plan.sender = others.randomElement(using: &random) ?? account.user
        switch feature {
        case .mention:
            let lead = "Hey "
            let tag = "@Casey Sample"
            plan.text = lead + tag + ", can you take a look at the rollout plan before tomorrow's sync?"
            plan.annotations = [
                Annotation(kind: .userMention(account.user.name), startIndex: lead.utf16.count, length: tag.utf16.count)
            ]
        case .longMessage:
            plan.text = FakeScript.longMessage
        case .link:
            plan.text = "Draft is here: https://docs.example.com/design/q4-roadmap - please comment by Friday."
        case .uploaded:
            plan.text = "Attaching the latest numbers."
            plan.attachments = [context.upload("Q3-report.pdf", "application/pdf", "q3-report-\(slot)")]
        case .drive:
            plan.text = "Budget sheet for next year, edit access for everyone in the space."
            plan.attachments = [drive("Budget 2027", FakeScript.Mime.gsheet, "1AbCdEfGhIjKlMnOpQrStUvWxYz")]
        case .deleted:
            plan.text = "Oops, wrong channel."
            plan.deleted = true
        }
    }

    // MARK: Reactions

    private static func randomReactions(_ context: Context, _ message: Message, _ random: inout SeededRandom) {
        let kinds = FakeScript.reactionEmoji.shuffled(using: &random).prefix(Int.random(in: 1...4, using: &random))
        for symbol in kinds {
            let roll = Double.random(in: 0...1, using: &random)
            let count =
                roll < 0.6
                ? Int.random(in: 1...3, using: &random)
                : roll < 0.9 ? Int.random(in: 4...7, using: &random) : Int.random(in: 8...12, using: &random)
            react(context, message, [(.unicode(symbol), count)], mine: Double.random(in: 0...1, using: &random) < 0.25)
        }
    }

    /// The first reaction of a group is the account's own when `mine` is set.
    private static func react(_ context: Context, _ message: Message, _ groups: [(Emoji, Int)], mine: Bool = false) {
        for (emoji, count) in groups {
            for index in 0..<count {
                let sender: FakeSender =
                    index == 0 && mine
                    ? .account(context.account) : .user(context.reactors[index % context.reactors.count])
                context.server.react(
                    message.name, emoji: emoji, by: sender, at: message.createTime.adding(.seconds(20 + index)))
            }
        }
    }

    // MARK: Showcase

    /// Dense, deterministic content at the end of three Studio A spaces so renders show every message kind.
    private static func showcase(
        _ context: Context, _ title: String, _ space: SpaceName, end: Date, others: [User]
    ) {
        var step = 0
        func next() -> Timestamp {
            step += 1
            return Timestamp(end.addingTimeInterval(Double(step) * 10))
        }
        func send(
            _ text: String, _ index: Int, annotations: [Annotation] = [], attachments: [Attachment] = [],
            quoted: QuotedMessage? = nil, card: String? = nil, gifs: [URL] = []
        ) -> Message {
            context.server.post(
                text, in: space, from: .user(others[index % others.count]), annotations: annotations,
                attachments: attachments, at: next(), gifURLs: gifs, quoted: quoted, cardsFallbackText: card)
        }
        func token(_ shortcode: String, in text: String, _ name: CustomEmojiName) -> Annotation {
            let range = (text as NSString).range(of: ":\(shortcode):")
            return Annotation(
                kind: .customEmoji(name, shortcode: shortcode), startIndex: range.location, length: range.length)
        }
        let emoji = context.emoji

        switch title {
        case "Engineering":
            let release = send("Release 4.2 is out 🚀🎉 Thanks everyone!", 0)
            react(
                context, release,
                [(.unicode("🚀"), 12), (.unicode("🎉"), 8), (.unicode("👍🏽"), 5), (.unicode("❤️"), 3)], mine: true)
            let photo = send("Offsite photo 👨‍👩‍👧‍👦 flags 🏳️‍🌈 🇧🇬 🇩🇪 🇯🇵 - thanks everyone 🙏🏽", 1)
            react(context, photo, [(.unicode("😍"), 4), (.unicode("😂"), 1)])
            let tones = send("Skin tones 👋🏻 👋🏼 👋🏽 👋🏾 👋🏿 and 👩🏽‍💻 👨🏿‍🚀 🧑‍🔬", 2)
            react(context, tones, [(.unicode("👍"), 2)], mine: true)
            let deploy = "Deploy finished :shipit: all checks green :lgtm: time to celebrate :party_parrot:"
            let custom = send(
                deploy, 3,
                annotations: [
                    token("shipit", in: deploy, emoji.shipit), token("lgtm", in: deploy, emoji.lgtm),
                    token("party_parrot", in: deploy, emoji.parrot),
                ])
            react(
                context, custom,
                [
                    (.custom(emoji.shipit, shortcode: "shipit"), 6), (.custom(emoji.lgtm, shortcode: "lgtm"), 2),
                    (.unicode("✅"), 3),
                ], mine: true)
            let wide = send("Which of these describes your Monday?", 4)
            let symbols = ["😀", "😂", "🤔", "👀", "🔥", "💯", "🙌", "😢", "🎯", "🧠", "⚡️", "🍕"]
            react(context, wide, symbols.enumerated().map { (Emoji.unicode($1), $0 + 1) })

        case "Releases":
            _ = send(
                "Build artifacts", 0,
                attachments: [
                    context.upload("screenshot-onboarding.png", "image/png", "show-png"),
                    context.upload("site-photo.jpg", "image/jpeg", "show-jpg"),
                    context.upload("celebrate.gif", "image/gif", "show-gif"),
                    context.upload("IMG_4021.heic", "image/heic", "show-heic"),
                ])
            _ = send("", 1, attachments: [context.upload("Release-notes-4.2.pdf", "application/pdf", "show-pdf")])
            _ = send("Release party", 2, gifs: [FakeLibrary.gifURL])
            _ = send(
                "Specs and exports", 2,
                attachments: [
                    context.upload("assets.zip", "application/zip", "show-zip"),
                    context.upload("Proposal-v2.docx", FakeScript.Mime.docx, "show-docx"),
                    context.upload("Forecast.xlsx", FakeScript.Mime.xlsx, "show-xlsx"),
                    context.upload("Kickoff.pptx", FakeScript.Mime.pptx, "show-pptx"),
                ])
            _ = send(
                "Recordings", 3,
                attachments: [
                    context.upload("demo-walkthrough.mp4", "video/mp4", "show-mp4"),
                    context.upload("keynote-rehearsal.mov", "video/quicktime", "show-mov"),
                    context.upload("customer-data-export-180MB.zip", "application/zip", "show-big"),
                ])
            _ = send(
                "For the board pack", 4,
                attachments: [
                    context.upload(
                        "Quarterly-business-review-final-FINAL-v3-with-comments-from-legal-and-finance-2026-Q3.pdf",
                        "application/pdf", "show-long")
                ])
            _ = send(
                "Drive links", 0,
                attachments: [
                    drive("Launch plan", FakeScript.Mime.gdoc, "drive-doc"),
                    drive("Budget 2027", FakeScript.Mime.gsheet, "drive-sheet"),
                    drive("All-hands deck", FakeScript.Mime.gslides, "drive-slides"),
                ])

        case "Design Reviews":
            let original = send("Can we ship the new onboarding flow before the freeze?", 0)
            let quote = QuotedMessage(
                name: original.name, lastUpdateTime: nil, snapshotSender: original.sender.name,
                snapshotText: original.text)
            _ = send("Agreed, but only if the copy review is done by Thursday.", 1, quoted: quote)
            _ = send(
                "", 2,
                card: "Build #482 passed on main: 214 tests, 0 failures. Open the run in CI to see the full report.")
            _ = send("", 3, attachments: [context.upload("onboarding-flow-v7.png", "image/png", "show-flow")])
            let lead = "Hey "
            let tag = "@Casey Sample"
            _ = send(
                lead + tag + ", could you sign off on the final mockups?", 4,
                annotations: [
                    Annotation(
                        kind: .userMention(context.account.user.name), startIndex: lead.utf16.count,
                        length: tag.utf16.count)
                ])

        default:
            break
        }
    }

    // MARK: Helpers

    private static func drive(_ name: String, _ type: String, _ id: String) -> Attachment {
        Attachment(contentName: name, contentType: type, source: .drive(fileID: id))
    }

    private static func sender(_ user: User, _ account: FakeAccount, _ bot: Bool) -> FakeSender {
        if user == account.user { return .account(account) }
        return bot ? .bot(user) : .user(user)
    }

    private static func setReadState(
        _ server: FakeChatServer, _ account: FakeAccount, _ space: SpaceName, unread: Int
    ) {
        let topLevel = server.messages(in: space).filter { !$0.isThreadReply && !$0.isDeleted }
        guard let newest = topLevel.last else { return }
        let fromOthers = topLevel.filter { $0.sender.name != account.user.name }
        guard unread > 0, !fromOthers.isEmpty else {
            server.setReadState(account, space: space, lastReadTime: newest.createTime)
            return
        }
        if unread >= fromOthers.count {
            server.setReadState(account, space: space, lastReadTime: nil)
        } else {
            let boundary = fromOthers[fromOthers.count - unread]
            server.setReadState(account, space: space, lastReadTime: boundary.createTime.adding(.milliseconds(-1)))
        }
    }
}
